window.STORY_CHAPTERS["c00e3e0d7f559868c"]={"id":"c00e3e0d7f559868c","lines":[{"uid":"talk.ch4_3_1000#originalText","id":"talk.ch4_3_1000","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"上级修剑士宿舍‧莱欧斯等人的起居室","en":"Elite Disciples' Dorm - Raios and Humbert's Living Room","ja":"上級修剣士寮・ライオスたちの部屋"},"kind":"caption"},{"uid":"talk.ch4_3_1001#originalText","id":"talk.ch4_3_1001","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"……所以，吾友尤吉欧修剑士 专程在安息日的傍晚时分来访， 不知有何贵干呢？","en":"So...what business does Sir Eugeo have with me on this day of rest?","ja":"……それで、我が友ユージオ修剣士におかれては安息日の夕刻に、いったいどのような御用かな?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1002#originalText","id":"talk.ch4_3_1002","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"因为听到一些关于那边那位 吉杰克修剑士的不好传闻，","en":"I heard a disturbing rumor about Disciple Zizek.","ja":"そちらのジーゼック修剣士に関して少々好ましからざる噂を耳にしましたので"},"kind":"dialogue"},{"uid":"talk.ch4_3_1002_2#originalText","id":"talk.ch4_3_1002_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"所以请恕我僭越，前来给予忠告。","en":"I deliver a warning: stop.","ja":"僭越ながら忠言に参りました"},"kind":"dialogue"},{"uid":"talk.ch4_3_1003#originalText","id":"talk.ch4_3_1003","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"什么……！？","en":"What?!","ja":"な……!?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1004#originalText","id":"talk.ch4_3_1004","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"喔……这真是让人高兴的 意外啊。","en":"Ohhh? I am surprised.","ja":"ほほう……これは意外であり望外のことでもあるな"},"kind":"dialogue"},{"uid":"talk.ch4_3_1004_2#originalText","id":"talk.ch4_3_1004_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"但很可惜的是， 我们完全不知道那些传闻是怎么回事。","en":"But I can't think of where the rumors possibly could have originated.","ja":"しかし惜しむらくはその噂とやら、まるで思い当たらない"},"kind":"dialogue"},{"uid":"talk.ch4_3_1005#originalText","id":"talk.ch4_3_1005","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……听说吉杰克同学对自己的 随侍练士，做出了相当下流的行为！","en":"We were informed that you are treating your page inappropriately.","ja":"……ジーゼック殿が、ご自身の傍付き練士に対して卑しき行いに及んでおられるとの話を聞いたのです!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1006#originalText","id":"talk.ch4_3_1006","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"实在太无礼了！","en":"How dare you!","ja":"無礼であろうッ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1007#originalText","id":"talk.ch4_3_1007","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"哎呀，别忽然就发火嘛，温贝尔。","en":"Humbert, sit down.","ja":"まあそういきり立つな、ウンベール"},"kind":"dialogue"},{"uid":"talk.ch4_3_1008#originalText","id":"talk.ch4_3_1008","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"不知道尤吉欧同学是从哪里 听到这种奇怪的传闻呢？","en":"Wherever did you hear such peculiar rumors, Sir Eugeo?","ja":"ユージオ殿は一体、どこからそのような珍妙な噂を聞きつけてきたのかな?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1009#originalText","id":"talk.ch4_3_1009","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是那些跟吉杰克同学随侍同寝室的 初等练士直接告诉我的。","en":"From Zizek's page's roommates.","ja":"ジーゼック殿の傍付きと同室の初等練士たちから直接話を聞いたのです"},"kind":"dialogue"},{"uid":"talk.ch4_3_1010#originalText","id":"talk.ch4_3_1010","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"是温贝尔的随侍主动请同寝室的 初等练士，","en":"Did Humbert's page ask her roommates to ask","ja":"ウンベールの傍付きが、自らの意思で公式に同室の初等練士を通じて"},"kind":"dialogue"},{"uid":"talk.ch4_3_1010_2#originalText","id":"talk.ch4_3_1010_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"透过尤吉欧同学 来向我们做出正式的抗议啰？","en":"you gentlemen for help?","ja":"ユージオ殿に抗議を依頼したと?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1011#originalText","id":"talk.ch4_3_1011","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……这么说，二位是否定有这回事啰？ 温贝尔同学，你没有命令","en":"Then you will deny he ordered Frenica to commit deviant acts with him,","ja":"……ならば、否定なさるのですね?　"},"kind":"dialogue"},{"uid":"talk.ch4_3_1011_2#originalText","id":"talk.ch4_3_1011_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"随侍芙蕾妮卡做出脱序的行为？","en":"yes?","ja":"ウンベール殿が、フレニーカに逸脱した行いを命じておられることを?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1012#originalText","id":"talk.ch4_3_1012","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"尤吉欧同学，","en":"Sir Eugeo,","ja":"ユージオ殿"},"kind":"dialogue"},{"uid":"talk.ch4_3_1012_2#originalText","id":"talk.ch4_3_1012_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"你就干脆说是违反学院规范怎么样？","en":"why don't you just be direct and accuse him of breaking school rules?","ja":"もっと解りやすく学院則違反と言ったらどうかね?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1013#originalText","id":"talk.ch4_3_1013","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"即使学院规范没有禁止， 身为指导初等练士的上级修剑士","en":"An immoral act is an immoral act,","ja":"学院則で禁じられていなくとも"},"kind":"dialogue"},{"uid":"talk.ch4_3_1013_2#originalText","id":"talk.ch4_3_1013_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"也有一些事情不该做吧！","en":"regardless of school rules!","ja":"初等練士を導くべき上級修剣士としてすべきではないこともあるでしょう!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1014#originalText","id":"talk.ch4_3_1014","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"哎呀……怎么样啊，温贝尔？ 尤吉欧同学所说的事， 你有什么头绪吗？","en":"Oh, dear, oh dear. Humbert, does any of what Sir Eugeo is saying ring a bell?","ja":"やれやれ……どうなんだ、ウンベールユージオ殿の仰ること、身に覚えがあるのかね?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1015#originalText","id":"talk.ch4_3_1015","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"怎么可能！","en":"Absolutely not!","ja":"とぉんでもない!　"},"kind":"dialogue"},{"uid":"talk.ch4_3_1015_2#originalText","id":"talk.ch4_3_1015_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"我完全不知道他在说些什么！","en":"I have no idea what he's talking about!","ja":"何を言われているのかさっぱり思い当たりませんな!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1016#originalText","id":"talk.ch4_3_1016","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"不过，我的确命令她做了几件 鸡毛蒜皮的小事。","en":"I do remember asking her to perform several trivial tasks.","ja":"ま、いくつか他愛ない世話を命じはしましたがね"},"kind":"dialogue"},{"uid":"talk.ch4_3_1017#originalText","id":"talk.ch4_3_1017","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"前几天和尤吉欧同学比赛， 我很丢脸地和你打成了平手。","en":"Ever since my duel with Sir Eugeo, which shamefully ended in a draw,","ja":"ユージオ殿との先日の立ち合いで情けなくも引き分けて以来"},"kind":"dialogue"},{"uid":"talk.ch4_3_1018#originalText","id":"talk.ch4_3_1018","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"之后我也痛定思痛地 开始重新锻炼自己。","en":"I have become a new man! I have plunged into my training.","ja":"私も心を入れ替えて鍛錬に打ち込んでおりましてな"},"kind":"dialogue"},{"uid":"talk.ch4_3_1019#originalText","id":"talk.ch4_3_1019","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"但是，因为之前不想让身体长出 丑陋的肌肉，而没有一直练习， 所以全身酸痛得不得了。","en":"But as I've avoided training that builds unsightly muscles before, sessions leave me in great pain.","ja":"だがこれまで、醜い筋肉がつくような稽古を控えていたせいもあって、全身が痛くて仕方ない"},"kind":"dialogue"},{"uid":"talk.ch4_3_1020#originalText","id":"talk.ch4_3_1020","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"在没办法的情况下， 只有每天晚上在洗澡时请芙蕾妮卡 帮我按摩僵硬的肌肉。","en":"So I merely asked Frenica to rub my body all over every night when I bathe.","ja":"やむなくフレニーカに、毎夕の湯浴みの折に体を揉み解して貰ったまでのこと"},"kind":"dialogue"},{"uid":"talk.ch4_3_1021#originalText","id":"talk.ch4_3_1021","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"什么……！","en":"What?!","ja":"な……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1022#originalText","id":"talk.ch4_3_1022","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"而且我为了怕她把制服弄湿， 还很宽容地要她只穿着内衣 就可以了喔。","en":"And, I was kind enough to have her strip to her underwear, so as not to soil her uniform.","ja":"そのうえ、制服が濡れては困ろうとフレニーカにも下着姿になることを許す寛大さですぞ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1023#originalText","id":"talk.ch4_3_1023","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"我实在搞不懂这算什么 下流脱序的行为呢！","en":"Just what part of that was inappropriate? I struggle to see it.","ja":"いったいこのどこが、卑しい逸脱行為なのか理解に苦しみますな!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1024#originalText","id":"talk.ch4_3_1024","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1025#originalText","id":"talk.ch4_3_1025","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"芙蕾妮卡初等练士 每天都过着痛苦的生活。","en":"Primary Trainee Frenica is in anguish every day.","ja":"フレニーカ初等練士は日々耐え難い思いをしています"},"kind":"dialogue"},{"uid":"talk.ch4_3_1026#originalText","id":"talk.ch4_3_1026","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"如果今后还不见改善的话， 我们也只能请求教官加以调查。","en":"If the situation does not improve,","ja":"改善が見られないようなら教官に調べを依頼することも考えなければならない"},"kind":"dialogue"},{"uid":"talk.ch4_3_1026_2#originalText","id":"talk.ch4_3_1026_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"请你自爱。","en":"I will request a full investigation.","ja":"そのおつもりで"},"kind":"dialogue"},{"uid":"talk.ch4_3_1027#originalText","id":"talk.ch4_3_1027","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"什么！？","en":"What?!","ja":"なにっ!?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1028#originalText","id":"talk.ch4_3_1028","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"悉听尊便。","en":"Fine. Do whatever you want.","ja":"ご自由にされるがよかろう?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1029#originalText","id":"talk.ch4_3_1029","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"上级修剑士宿舍‧桐人等人的起居室","en":"Elite Disciples' Dorm - Kirito and Eugeo's Living Room","ja":"上級修剣士寮・キリトたちの部屋"},"kind":"caption"},{"uid":"talk.ch4_3_1030#originalText","id":"talk.ch4_3_1030","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"尤吉欧，你冷静一点。","en":"Stay calm, Eugeo.","ja":"落ち着けよ、ユージオ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1031#originalText","id":"talk.ch4_3_1031","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……我还以为你会比我更早爆发呢。","en":"I thought you would blow your top before me, Kirito.","ja":"……僕より先に、キリトのほうが爆発すると思ってたけどな"},"kind":"dialogue"},{"uid":"talk.ch4_3_1032#originalText","id":"talk.ch4_3_1032","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"如果有带剑的话就很危险了。","en":"If weapons were involved, ","ja":"剣があったら危なかったな"},"kind":"dialogue"},{"uid":"talk.ch4_3_1032_2#originalText","id":"talk.ch4_3_1032_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不过……想说他们应该有什么阴谋， 所以我才在观察情况。","en":"there'd have been trouble. But, I was watching them for clues.","ja":"ただ……何か裏があるんじゃないかと思って、様子を見てたんだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1033#originalText","id":"talk.ch4_3_1033","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"想说这搞不好是针对你 而设下的圈套。","en":"They might have been trying to lure you into a trap, Eugeo.","ja":"もしかしたらこれはユージオを狙った罠なんじゃないかってさ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1034#originalText","id":"talk.ch4_3_1034","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦……？","en":"Huh?","ja":"え……?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1035#originalText","id":"talk.ch4_3_1035","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"比如你在他们的挑衅下说得太过火， 他们就会认定这是无礼行为，","en":"If you'd lost your temper, they might have punished you with","ja":"お前が挑発に乗って言いすぎたらそれを逸礼行為に認定して"},"kind":"dialogue"},{"uid":"talk.ch4_3_1035_2#originalText","id":"talk.ch4_3_1035_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"并对你施加最为严厉的惩罚。","en":"the maximum penalty.","ja":"最大限の懲罰を科すつもりだった、とか"},"kind":"dialogue"},{"uid":"talk.ch4_3_1037#originalText","id":"talk.ch4_3_1037","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"…………","en":"...","ja":"…………"},"kind":"dialogue"},{"uid":"talk.ch4_3_1038#originalText","id":"talk.ch4_3_1038","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"如果温贝尔再次污辱芙蕾妮卡， 为了可以立刻请教官调查，","en":"You should at least be ready to request the investigation","ja":"今後もウンベールがフレニーカを辱めるようなら"},"kind":"dialogue"},{"uid":"talk.ch4_3_1038_2#originalText","id":"talk.ch4_3_1038_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们得先做好准备才行。","en":"if Humbert assaults Frenica again.","ja":"すぐに調査を要請できるよう準備だけはしとくべきだろう"},"kind":"dialogue"},{"uid":"talk.ch4_3_1039#originalText","id":"talk.ch4_3_1039","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"尤吉欧，我不在的时候 不论那两个家伙对你说什么，","en":"Eugeo, if they say anything to you when I'm not around,","ja":"ユージオ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1039_2#originalText","id":"talk.ch4_3_1039_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你都要注意不能像刚才那样发火喔。","en":"try not to lose your temper.","ja":"俺のいないとこでまた連中に何か言われてもさっきみたいに熱くならないよう気をつけろよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1040#originalText","id":"talk.ch4_3_1040","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我、我知道啦。Stay cool对吧？","en":"I got it. Stay cool, right?","ja":"わ、解ってるよステイ・クール、だろ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1041#originalText","id":"talk.ch4_3_1041","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没错， Stay cool。","en":"That's right. Stay cool.","ja":"そうだステイ・クール"},"kind":"dialogue"},{"uid":"talk.ch4_3_1042#originalText","id":"talk.ch4_3_1042","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"隔日 尤吉欧的寝室","en":"The next day, Eugeo's bedroom","ja":"翌日 ユージオの寝室"},"kind":"caption"},{"uid":"talk.ch4_3_1043#originalText","id":"talk.ch4_3_1043","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"报告尤吉欧上级修剑士！ 今天的打扫已经完成了！","en":"Elite Disciple Eugeo, reporting in! I have finished cleaning for today.","ja":"ユージオ上級修剣士殿。ご報告します!本日の掃除、完了しました!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1044#originalText","id":"talk.ch4_3_1044","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好，辛苦妳了。谢谢妳每天帮忙打扫。","en":"Thank you. You always do such a wonderful job.","ja":"はい、ご苦労さまいつもありがとう"},"kind":"dialogue"},{"uid":"talk.ch4_3_1045#originalText","id":"talk.ch4_3_1045","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"哪里，这本来就是随侍的工作！","en":"It is my duty to serve!","ja":"いえ、傍付きの仕事ですから!"},"kind":"dialogue"},{"uid":"talk.ch4_3_1046#originalText","id":"talk.ch4_3_1046","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那个……不好意思， 我可以和妳谈一下吗？","en":"So...sorry,","ja":"ええと……悪いんだけど"},"kind":"dialogue"},{"uid":"talk.ch4_3_1046_2#originalText","id":"talk.ch4_3_1046_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"先坐下来吧。","en":"but can you have a seat? I want to talk to you about something.","ja":"ちょっと話をさせて貰っていいかな座ってよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1047#originalText","id":"talk.ch4_3_1047","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"啊…… 那、那就失礼了。","en":"Oh! W-well, then, thank you.","ja":"はっ……そ、それでは、失礼致します"},"kind":"dialogue"},{"uid":"talk.ch4_3_1048#originalText","id":"talk.ch4_3_1048","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"关于芙蕾妮卡那件事…… 我昨天已经跟温贝尔抗议过了。","en":"It's about Frenica... I gave Humbert a stern talking to yesterday.","ja":"フレニーカの件だけど……昨日、ウンベールに抗議しておいたよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1049#originalText","id":"talk.ch4_3_1049","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我想那家伙也不想把事情闹大， 所以应该不会再下达脱序的命令了。","en":"He probably doesn't want things to escalate, so he shouldn't abuse her anymore.","ja":"あいつもこれ以上大ごとにはしたくないだろうからもう逸脱した命令は出さないはずだよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1050#originalText","id":"talk.ch4_3_1050","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……太好了。","en":"Oh, good...","ja":"……よかった"},"kind":"dialogue"},{"uid":"talk.ch4_3_1051#originalText","id":"talk.ch4_3_1051","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"还有……我已经知道，","en":"Also...I learned that","ja":"それに……今回の件は僕がウンベールと立ち合ったことが"},"kind":"dialogue"},{"uid":"talk.ch4_3_1051_2#originalText","id":"talk.ch4_3_1051_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这次的事件都是因为 我和温贝尔的比试而起……","en":"Humbert was mistreating her to get back at me.","ja":"そもそもの原因だってことがわかったんだ……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1052#originalText","id":"talk.ch4_3_1052","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我也想好好跟她道歉， 妳可以帮我找个机会吗……？","en":"So I want to apologize to Frenica personally. Could you arrange that?","ja":"一度、僕からもちゃんと彼女に謝りたいんだけど機会を作ってもらえるかな……?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1053#originalText","id":"talk.ch4_3_1053","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……是……这样啊……","en":"You...want to apologize?","ja":"……そう……ですか……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1054#originalText","id":"talk.ch4_3_1054","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不，这不是尤吉欧学长的责任。我会把学长说的话传达给芙蕾妮卡。","en":"But it's not your fault, Eugeo. I'll just relay your message to her.","ja":"いえ、ユージオ先輩の責任ではありませんフレニーカには先輩のお言葉だけ伝えておきます"},"kind":"dialogue"},{"uid":"talk.ch4_3_1055#originalText","id":"talk.ch4_3_1055","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"就是……","en":"He's, um...","ja":"あの……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1055_2#originalText","id":"talk.ch4_3_1055_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我、我可以稍微 到学长的身边去一下吗？","en":"c-can I come closer to you?","ja":"す、少しお傍に行ってもいいですか?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1056#originalText","id":"talk.ch4_3_1056","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦…… 嗯、嗯。","en":"Huh? O-okay.","ja":"え……う、うん"},"kind":"dialogue"},{"uid":"talk.ch4_3_1057#originalText","id":"talk.ch4_3_1057","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我从修剑学院毕业后没多久， 就会继承休特里涅家，","en":"After I graduate,","ja":"私は、修剣学院を卒業したらシュトリーネン家を継ぎ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1057_2#originalText","id":"talk.ch4_3_1057_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"并从同等级或是 高一等的爵士家请丈夫过来入赘……","en":"I'm going to succeed my House and I'll have to choose a noble husband.","ja":"同格か一等上の爵家から夫を迎えることになります……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1058#originalText","id":"talk.ch4_3_1058","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我很害怕。","en":"And I'm scared.","ja":"私、怖いんです"},"kind":"dialogue"},{"uid":"talk.ch4_3_1058_2#originalText","id":"talk.ch4_3_1058_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"如果成为我丈夫的人 是像吉杰克学长那样的人呢……？","en":"What if my husband turns out to be like Zizek?","ja":"もし、私の夫となった人がジーゼック殿みたいな人だったら……?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1059#originalText","id":"talk.ch4_3_1059","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"只要想到对方可能是毫无荣誉感， 能够随便对别人做出","en":"What if he's a prideless sociopath who enjoys hurting others?","ja":"誇りを持たずに、平気で酷いことをするような人だったらどうしようって思うと……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1059_2#originalText","id":"talk.ch4_3_1059_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"残酷行为的人……我就非常害怕……","en":"I'm just...so scared...","ja":"怖くて……私……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1060#originalText","id":"talk.ch4_3_1060","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1061#originalText","id":"talk.ch4_3_1061","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦……缇洁……！？","en":"Huh? Tiese?!","ja":"えっ……ティーゼ……!?"},"kind":"dialogue"},{"uid":"talk.ch4_3_1062#originalText","id":"talk.ch4_3_1062","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"尤吉欧学长……","en":"Oh, Eugeo...","ja":"ユージオ先輩……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1062_2#originalText","id":"talk.ch4_3_1062_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我……有件事想拜托你。","en":"I...I have a favor to ask of you.","ja":"私、その……先輩に、お願いがあるんです"},"kind":"dialogue"},{"uid":"talk.ch4_3_1063#originalText","id":"talk.ch4_3_1063","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"尤吉欧学长……请你一定要成为 学院代表，","en":"Please become valedictorian, win the sword tournament,","ja":"ユージオ先輩……きっと、きっと学院代表になって"},"kind":"dialogue"},{"uid":"talk.ch4_3_1063_2#originalText","id":"talk.ch4_3_1063_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"然后在剑武大会里获胜， 接着参加四帝国统一大会。","en":"and compete in the Unity Tournament. ","ja":"剣武大会にも勝って四帝国統一大会に出てくださいね"},"kind":"dialogue"},{"uid":"talk.ch4_3_1064#originalText","id":"talk.ch4_3_1064","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"当、当然…… 我就是以这个为目标……","en":"W-well, of course I will. Those were always my goals.","ja":"そ、それは……もちろん僕もそれを目指してるけど……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1065#originalText","id":"talk.ch4_3_1065","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我、我听说在统一大会里拿到前几名，","en":"If you win the tournament,","ja":"と、統一大会で上位に入れば"},"kind":"dialogue"},{"uid":"talk.ch4_3_1065_2#originalText","id":"talk.ch4_3_1065_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"就能和初等练士宿舍的阿滋利卡老师 一样在这代被任命为爵士。","en":"I hear you get to be knighted like Ms. Azurika was.","ja":"初等練士寮のアズリカ先生みたいに一代爵士として叙任されると聞きました"},"kind":"dialogue"},{"uid":"talk.ch4_3_1066#originalText","id":"talk.ch4_3_1066","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"那个，如果学长能成为爵士………… 就当我……就当我的…………","en":"So, if that happens to you... will you...will you...","ja":"あの……もし先輩がそうなれたら…………私……私の…………"},"kind":"dialogue"},{"uid":"talk.ch4_3_1067#originalText","id":"talk.ch4_3_1067","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1068#originalText","id":"talk.ch4_3_1068","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（我之所以要参加统一大会，","en":"(I want to win the tournament so I can become an Integrity Knight","ja":"(僕が統一大会を目指しているのは整合騎士になって、アリスともう一度会う)"},"kind":"dialogue"},{"uid":"talk.ch4_3_1068_2#originalText","id":"talk.ch4_3_1068_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唯一的目的就是成为集成骑士， 再次见到爱丽丝……）","en":"and save Alice...)","ja":"(ただそのため……)"},"kind":"dialogue"},{"uid":"talk.ch4_3_1069#originalText","id":"talk.ch4_3_1069","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯……我知道了。等大会结束之后，我一定会去找妳。","en":"Okay... When the tournament's over, I'll come visit you.","ja":"うん……わかった大会が終わったら、きっと君に会いにいくよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_1070#originalText","id":"talk.ch4_3_1070","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我也会……我也会变得更强大，","en":"I'll become stronger, too!","ja":"……私も、私も強くなります"},"kind":"dialogue"},{"uid":"talk.ch4_3_1070_2#originalText","id":"talk.ch4_3_1070_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"强大到能确实把正确的事， 还有必须说出口的事说出来。","en":"Strong enough to say the right thing when it's not easy to.","ja":"正しいこと、言わなきゃいけないことをきちんと言えるくらい、強く"},"kind":"dialogue"},{"uid":"talk.ch4_3_2000#originalText","id":"talk.ch4_3_2000","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"人界历380年 5月22日","en":"May 22, 380 HEC","ja":"人界暦380年 5月22日"},"kind":"caption"},{"uid":"talk.ch4_3_2001#originalText","id":"talk.ch4_3_2001","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"刚才那是四点半的钟声吗？","en":"That was the four-thirty bell, eh?","ja":"今のは、4時半の鐘か"},"kind":"dialogue"},{"uid":"talk.ch4_3_2002#originalText","id":"talk.ch4_3_2002","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"缇洁她们真慢，","en":"Tiese and Ronie have never been late","ja":"遅いな、ティーゼたち"},"kind":"dialogue"},{"uid":"talk.ch4_3_2002_2#originalText","id":"talk.ch4_3_2002_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"她们从来没有这么晚才来打扫啊。","en":"for their cleaning duties before.","ja":"これまで掃除に遅れたことなんて一度もなかったのに"},"kind":"dialogue"},{"uid":"talk.ch4_3_2003#originalText","id":"talk.ch4_3_2003","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"偏偏这种时候桐人也不在， 总觉得有种不好的预感……","en":"And Kirito's not here, either... I've got a bad feeling about this.","ja":"こんなときに限ってキリトもいないし何か嫌な感じがする……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2004#originalText","id":"talk.ch4_3_2004","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，是敲门声。太好了，我正在担……","en":"Oh, someone's at the door. Thank goodness. I was wor...","ja":"あ、ノックの音だよかった、心配し……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2005#originalText","id":"talk.ch4_3_2005","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"那个……","en":"Um...","ja":"あの……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2005_2#originalText","id":"talk.ch4_3_2005_2","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"请问是尤吉欧上级修剑士吗……？","en":"are you Elite Disciple Eugeo?","ja":"ユージオ上級修剣士殿でしょうか……?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2006#originalText","id":"talk.ch4_3_2006","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我…… 我是芙蕾妮卡‧歇丝基初等练士。","en":"I'm F-Frenica Cesky, primary trainee.","ja":"わ……私はフレニーカ・シェスキ初等練士です"},"kind":"dialogue"},{"uid":"talk.ch4_3_2007#originalText","id":"talk.ch4_3_2007","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"没、没有事先约好就冒昧来访， 真的很抱歉。","en":"I'm sorry to barge in uninvited.","ja":"ご、ご面会の約束もなしにお訪ねして申し訳ありません"},"kind":"dialogue"},{"uid":"talk.ch4_3_2008#originalText","id":"talk.ch4_3_2008","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"妳就是……芙蕾妮卡吗？","en":"So you're Frenica...","ja":"君が……フレニーカか"},"kind":"dialogue"},{"uid":"talk.ch4_3_2009_1#originalText","id":"talk.ch4_3_2009_1","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"那个……之前承蒙尤吉欧修剑士您的照顾","en":"Um... Elite Disciple Eugeo.","ja":"あの……ユージオ修剣士殿にはこのたび"},"kind":"dialogue"},{"uid":"talk.ch4_3_2009#originalText","id":"talk.ch4_3_2009","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我由衷感谢您帮忙处理 我和吉杰克学长之间的纷争。","en":"I thank you from the bottom of my heart for helping me deal with Zizek.","ja":"私とジーゼック殿のことでご尽力を賜りまして心より感謝しております"},"kind":"dialogue"},{"uid":"talk.ch4_3_2010#originalText","id":"talk.ch4_3_2010","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"但是……吉杰克学长他……今天晚上……","en":"But...Zizek is still... He still orders me to perform those tasks, ","ja":"ですが……ジーゼック殿は……本日の夜間に、私に"},"kind":"dialogue"},{"uid":"talk.ch4_3_2011_2#originalText","id":"talk.ch4_3_2011_2","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"又命令我…… 做出难以启齿的服务……","en":"which pains me to explain, every night.","ja":"この場では少々説明の難しいご奉仕を命じておられまして……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2012#originalText","id":"talk.ch4_3_2012","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我、我…… 我告诉缇洁和罗妮耶……","en":"And if I have to continue as his page, doing such tasks...","ja":"わ、私……このようなご命令が続くくらいならいっそ学院を辞めようと思って"},"kind":"dialogue"},{"uid":"talk.ch4_3_2013#originalText","id":"talk.ch4_3_2013","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"如果要继续接受这种命令的话， 干脆就退学离开好了。","en":"I told Tiese and Ronie I would rather quit the Academy than live like that.","ja":"ティーゼとロニエに、打ち明けたのです"},"kind":"dialogue"},{"uid":"talk.ch4_3_2014#originalText","id":"talk.ch4_3_2014","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"听到我说的话之后， 她们便说要直接请求吉杰克学长 别再这么做而离开宿舍……","en":"When they heard this, they left the dorm to speak directly to Zizek.","ja":"それを聞いたふたりは、直接ジーゼック殿に嘆願すると言って寮を出ていったのですが……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2015#originalText","id":"talk.ch4_3_2015","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"然后她们就一直没回来……","en":"And they haven't come back...","ja":"それきり戻ってこなくて……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2016#originalText","id":"talk.ch4_3_2016","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"妳说什么！","en":"What?!","ja":"なんだって!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2017#originalText","id":"talk.ch4_3_2017","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"妳在这里等桐人。","en":"You stay here and wait for Kirito.","ja":"君はここでキリトを待ってて"},"kind":"dialogue"},{"uid":"talk.ch4_3_2018#originalText","id":"talk.ch4_3_2018","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（打从一开始他们的目标就是这个吗？ 不是针对我，而是缇洁她们……？）","en":"(Was this their plan all along? They wanted to hurt Tiese and Ronie, not me?)","ja":"(最初からそれが目的だったのか……?僕じゃなく、ティーゼたちを……?)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2300#originalText","id":"talk.ch4_3_2300","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"上级修剑士宿舍‧莱欧斯等人的起居室","en":"Elite Disciples' Dorm - Raios and Humbert's Living Room","ja":"上級修剣士寮・ライオスたちの部屋"},"kind":"caption"},{"uid":"talk.ch4_3_2301#originalText","id":"talk.ch4_3_2301","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"请进！","en":"Come on in!","ja":"どうぞ入ってくれたまえよ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2302#originalText","id":"talk.ch4_3_2302","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"我们刚好开了一瓶西帝国产的 五十年红酒，来喝一杯如何？","en":"I've just opened a 50-year-old Four Empires import. How about a glass?","ja":"ちょうど、西帝国産の50年物を開けたところだが、どうだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2303#originalText","id":"talk.ch4_3_2303","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"这可是平民喝不到的美酒喔。","en":"Most peasants can't even dream of tasting it.","ja":"平民の口には入らぬ代物だぞ?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2304#originalText","id":"talk.ch4_3_2304","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不，不用了。重点是，吉杰克修剑士……","en":"No thank you. Zizek, I came by because...","ja":"いえ、結構ですそれよりジーゼック修剣士殿……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2305#originalText","id":"talk.ch4_3_2305","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我们的随侍缇洁初等练士和 罗妮耶初等练士，","en":"Did our pages,","ja":"本日この部屋に、僕たちの傍付き"},"kind":"dialogue"},{"uid":"talk.ch4_3_2305_2#originalText","id":"talk.ch4_3_2305_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天有到二位的房间来吗？","en":"Tiese and Ronie, come by your room today?","ja":"ティーゼ初等練士とロニエ初等練士が訪ねては参りませんでしたか?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2306#originalText","id":"talk.ch4_3_2306","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"嗯……那两个人原来是尤吉欧同学与 桐人同学的随侍吗？","en":"Hmmm... those girls are your pages?","ja":"ふぅむ。……あのふたりはユージオ殿とキリト殿の傍付きであったか"},"kind":"dialogue"},{"uid":"talk.ch4_3_2307#originalText","id":"talk.ch4_3_2307","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"实在是两名相当有勇气的初等练士， 真不愧是二位的随侍。","en":"They certainly have spunk. Knowing you're their mentor explains a lot.","ja":"実に勇敢なる初等練士たちだなさすがはおふたりの傍付きだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2308#originalText","id":"talk.ch4_3_2308","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"不过，还是得注意一下。","en":"But you must be careful.","ja":"ただ、気をつけねばならないよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2309#originalText","id":"talk.ch4_3_2309","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"过于激动的态度有时候会变成无礼。你不这么认为吗，尤吉欧修剑士？","en":"Sometimes having grit can be detrimental. Wouldn't you say so, Sir Eugeo?","ja":"威勢の良さは時として非礼ともなるそうは思わないか、ユージオ修剣士殿"},"kind":"dialogue"},{"uid":"talk.ch4_3_2310#originalText","id":"talk.ch4_3_2310","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"下次有机会再恭听您的高见。","en":"I would love for you to impart your wisdom some other time.","ja":"ご高説はまたの機会に拝聴します"},"kind":"dialogue"},{"uid":"talk.ch4_3_2311#originalText","id":"talk.ch4_3_2311","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"缇洁和罗妮耶现在在哪里？","en":"Now, where are Tiese and Ronie?","ja":"ティーゼとロニエは今どこにいるのです"},"kind":"dialogue"},{"uid":"talk.ch4_3_2312#originalText","id":"talk.ch4_3_2312","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"呵…… 跟我来吧。","en":"Humph! Follow me.","ja":"フンッ……ついてこい"},"kind":"dialogue"},{"uid":"talk.ch4_3_2313#originalText","id":"talk.ch4_3_2313","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"什……这……这到底是！？","en":"What... What have you done?!","ja":"な……これは……いったい!?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2314#originalText","id":"talk.ch4_3_2314","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这到底是怎么回事，莱欧斯同学！","en":"What have you done, Raios?!","ja":"どういうことです、ライオス殿!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2315#originalText","id":"talk.ch4_3_2315","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"这也是不得已的处置啊，","en":"This is deserved punishment.","ja":"これはやむを得ない処置なのだよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2315_2#originalText","id":"talk.ch4_3_2315_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"因为她们两个对我们做出 极为无礼的举动。","en":"They were horribly discourteous to us.","ja":"ふたりは、我らに甚だしい非礼を働いたのだからな"},"kind":"dialogue"},{"uid":"talk.ch4_3_2316#originalText","id":"talk.ch4_3_2316","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"什么……无礼的举动…………","en":"Dis...courteous?","ja":"非礼……とは…………"},"kind":"dialogue"},{"uid":"talk.ch4_3_2317#originalText","id":"talk.ch4_3_2317","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"这两个下级贵族的小女孩， 竟然敢侮辱我这个四等爵士……","en":"These ill-bred faux aristocrat  daughters falsely accused me...","ja":"あの下級貴族の娘どもはこともあろうに、四等爵士のこの私が"},"kind":"dialogue"},{"uid":"talk.ch4_3_2318#originalText","id":"talk.ch4_3_2318","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"说我毫无理由就虐待自己的随侍 来满足欲望。","en":"...of abusing my position of power to unleash my passions on my own page willy-nilly.","ja":"自分の傍付きを理由なく虐げ欲望を満たしているなどと侮辱してくれたのよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2319#originalText","id":"talk.ch4_3_2319","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"身为次席上级修剑士的我， 明明只是在导正芙蕾妮卡而已。","en":"I am the esteemed second chair. I am giving Frenica excellent training.","ja":"次席上級修剣士としてフレニーカを正しく導こうとしている、この私をだぞ?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2320#originalText","id":"talk.ch4_3_2320","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"…………！","en":"Grrr!","ja":"…………ッ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2321#originalText","id":"talk.ch4_3_2321","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"不只如此。","en":"And that is not all.","ja":"それだけではないのだよ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2322#originalText","id":"talk.ch4_3_2322","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"这两个人还说和温贝尔 同寝室的我也有责任。","en":"They claim I am also to blame, since I share a room with Humbert.","ja":"あのふたりは、ウンベールと同室の私にも責任がある。などと言ってくれてね"},"kind":"dialogue"},{"uid":"talk.ch4_3_2323#originalText","id":"talk.ch4_3_2323","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"只不过是六等爵士家的小女孩， 竟然敢对三等爵士家的我说出","en":"This 6th rank girl dared ask me,","ja":"三等爵家の私が、六等爵家の娘ごときに"},"kind":"dialogue"},{"uid":"talk.ch4_3_2323_2#originalText","id":"talk.ch4_3_2323_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"『你没有贵族的荣誉感吗』这种话！","en":"a 3rd rank noble,  if I had no pride!","ja":"『貴族の誇りはないのですか』などと言われようとは!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2324#originalText","id":"talk.ch4_3_2324","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……但是，莱欧斯同学， 就算有这样的事情……","en":"But Raios, even if they were falsely accusing you of something...","ja":"……ですが、ライオス殿仮にそうだったとしても……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2325#originalText","id":"talk.ch4_3_2325","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"把她们绑起来并且关在寝室， 也是超出《修剑士惩罚权》的","en":"Tying them up in your bedroom like this far exceeds","ja":"縄で縛り上げ、寝室に閉じ込めるなど"},"kind":"dialogue"},{"uid":"talk.ch4_3_2325_2#originalText","id":"talk.ch4_3_2325_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"脱序行为吧……！","en":"your disciplinary authority as an Elite Disciple!","ja":"《修剣士懲罰権》を甚だしく逸脱した行いでしょう……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2326#originalText","id":"talk.ch4_3_2326","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"《修剑士惩罚权》？","en":"As an Elite Disciple?","ja":"《修剣士懲罰権》?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2327#originalText","id":"talk.ch4_3_2327","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"你忘了学院规范里 还有这么一条附记吗？","en":"Have you forgotten the addendum to the school rules?","ja":"学院則には次のように付記してあるのをお忘れかな?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2328#originalText","id":"talk.ch4_3_2328","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"『──另外， 一切惩罚皆以上级法的规定为优先』。","en":"“In regards to disciplinary action, precedence is given to the higher laws.”","ja":"『――なお、全ての懲罰において上級法の規定を優先す』と"},"kind":"dialogue"},{"uid":"talk.ch4_3_2329#originalText","id":"talk.ch4_3_2329","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"所谓的上级法，就是禁忌目录， 还有帝国基本法。","en":"The “higher laws\" refer to the Taboo Index and Basic Imperial Law.","ja":"上級法とは禁忌目録そして帝国基本法のことだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2330#originalText","id":"talk.ch4_3_2330","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"也就是说…… 身为三等爵士家长子的我， 对这两个六等爵士家出身的女孩……","en":"In other words...since I am a 3rd rank nobleman, and they are 6th rank...","ja":"つまり……三等爵家の長子たる私は六等爵家出身の娘たちに"},"kind":"dialogue"},{"uid":"talk.ch4_3_4000#originalText","id":"talk.ch4_3_4000","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"修剑学院‧管理栋‧地下禁闭室","en":"Swordcraft Academy - Administrative Building - Underground Detention Cell","ja":"修剣学院・管理棟・地下懲罰房"},"kind":"caption"},{"uid":"talk.ch4_3_4001#originalText","id":"talk.ch4_3_4001","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"出来吧。","en":"Come out.","ja":"出なさい"},"kind":"dialogue"},{"uid":"talk.ch4_3_4002#originalText","id":"talk.ch4_3_4002","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"System call。","en":"System Call.","ja":"システム・コール"},"kind":"dialogue"},{"uid":"talk.ch4_3_4002_2#originalText","id":"talk.ch4_3_4002_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"Generate luminous element。Reconstruct lost organ。","en":"Generate Luminous Element. Reconstruct Lost Organ.","ja":"ジェネレート・ルミナス・エレメントリコンストラクト・ロスト・オーガ"},"kind":"dialogue"},{"uid":"talk.ch4_3_4003#originalText","id":"talk.ch4_3_4003","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"张开右眼看看吧。","en":"Open your right eye.","ja":"右眼を開けてみなさい"},"kind":"dialogue"},{"uid":"talk.ch4_3_4004#originalText","id":"talk.ch4_3_4004","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……是。","en":"Okay.","ja":"……はい"},"kind":"dialogue"},{"uid":"talk.ch4_3_4005#originalText","id":"talk.ch4_3_4005","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"谢、谢谢您， 阿滋利卡老师！","en":"Thank you so much, Ms. Azurika!","ja":"あ、ありがとうございます!アズリカ先生"},"kind":"dialogue"},{"uid":"talk.ch4_3_4006#originalText","id":"talk.ch4_3_4006","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"不客气。更重要的是……","en":"No problem.","ja":"いえ。それより……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4006_2#originalText","id":"talk.ch4_3_4006_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"尤吉欧修剑士，还有桐人修剑士。我必须把你们交给前来迎接你们的人。","en":"But Eugeo...and Kirito, I must hand you over now.","ja":"ユージオ修剣士、そしてキリト修剣士あなたたちを迎えの者に引き渡さねばなりません"},"kind":"dialogue"},{"uid":"talk.ch4_3_4007#originalText","id":"talk.ch4_3_4007","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"在那之前，我要先告诉你们。","en":"But before I do, I have something to tell you.","ja":"その前に、これだけは言っておきます"},"kind":"dialogue"},{"uid":"talk.ch4_3_4008#originalText","id":"talk.ch4_3_4008","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"……尤吉欧修剑士， 你破除了我无法破除的封印。","en":"Eugeo...you broke the seal I could not break.","ja":"……ユージオ修剣士あなたは、私に破れなかった封印を破った"},"kind":"dialogue"},{"uid":"talk.ch4_3_4009#originalText","id":"talk.ch4_3_4009","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你一定能到达我无法到达的境界……","en":"I'm sure you will go places I never could.","ja":"あなたならばきっと私に行けなかったところまで行けるはず……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4009_2#originalText","id":"talk.ch4_3_4009_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"相信你的剑，还有你的朋友吧。","en":"Trust your sword... and your friend.","ja":"その剣と、そして友を信じなさい"},"kind":"dialogue"},{"uid":"talk.ch4_3_4010#originalText","id":"talk.ch4_3_4010","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4011#originalText","id":"talk.ch4_3_4011","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"再来是桐人修剑士。","en":"And Kirito...","ja":"そして、キリト修剣士"},"kind":"dialogue"},{"uid":"talk.ch4_3_4011_2#originalText","id":"talk.ch4_3_4011_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"结果……我到最后还是无法了解 你究竟是什么人。","en":"I still don't know who you really are.","ja":"あなたが何者なのか……私にも、ついに解りませんでした"},"kind":"dialogue"},{"uid":"talk.ch4_3_4012#originalText","id":"talk.ch4_3_4012","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"但是，当你抵达那座塔时， 一定会有什么事情发生。","en":"But when you reach that tower, I bet something of significance will unfold.","ja":"ですが、あなたがあの塔に達した時きっと何かが起きる"},"kind":"dialogue"},{"uid":"talk.ch4_3_4013#originalText","id":"talk.ch4_3_4013","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"我会在这里祈祷， 希望你的前方有光明。","en":"I pray that the Light will guide you both.","ja":"その先に光があらんことを私はこの場所で祈っています"},"kind":"dialogue"},{"uid":"talk.ch4_3_4014#originalText","id":"talk.ch4_3_4014","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"我会永远为你祈祷。","en":"Always.","ja":"ずっと"},"kind":"dialogue"},{"uid":"talk.ch4_3_4015#originalText","id":"talk.ch4_3_4015","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"修剑学院‧大修练场","en":"Swordcraft Academy - Main Training Hall","ja":"修剣学院・大修練場"},"kind":"caption"},{"uid":"talk.ch4_3_4016#originalText","id":"talk.ch4_3_4016","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4017#originalText","id":"talk.ch4_3_4017","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4018#originalText","id":"talk.ch4_3_4018","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……我是北圣托利亚帝立修剑学院的 尤吉欧上级修剑士。","en":"I am Elite Disciple Eugeo, of northern Centoria's Imperial Academy of Swordcraft.","ja":"……北セントリア帝立修剣学院所属ユージオ上級修剣士です"},"kind":"dialogue"},{"uid":"talk.ch4_3_4019#originalText","id":"talk.ch4_3_4019","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我是同一学院的桐人。","en":"And I'm Kirito, of same rank and school.","ja":"同じくキリトです"},"kind":"dialogue"},{"uid":"talk.ch4_3_4020#originalText","id":"talk.ch4_3_4020","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（我好像曾经在哪里见过 这种蓝色与金色的搭配……）","en":"(This blue and golden color combination...I've seen it somewhere before.)","ja":"(この青色と、金色の取り合わせどこかで、見たことがあるような……)"},"kind":"dialogue"},{"uid":"talk.ch4_3_4021#originalText","id":"talk.ch4_3_4021","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我是统领圣托利亚市域的 公理教会集成骑士──","en":"Centoria Regional Headquarters, Axiom Church Integrity Knight,","ja":"セントリア市域統括公理教会整合騎士――"},"kind":"dialogue"},{"uid":"talk.ch4_3_4021_2#originalText","id":"talk.ch4_3_4021_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"爱丽丝‧辛赛西斯‧萨蒂。","en":"Alice Synthesis Thirty.","ja":"アリス・シンセシス・サーティです"},"kind":"dialogue"},{"uid":"talk.ch4_3_4022#originalText","id":"talk.ch4_3_4022","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……爱丽丝……？ 是妳吗……？","en":"Alice...?  Is that really you?","ja":"……アリス……?　君なのか……?"},"kind":"dialogue"},{"uid":"talk.ch4_3_4023#originalText","id":"talk.ch4_3_4023","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"爱丽丝……！","en":"Alice...!","ja":"アリス……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_4024#originalText","id":"talk.ch4_3_4024","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"尤吉欧！ 你没事吧！？","en":"Eugeo! Are you okay?!","ja":"ユージオ!大丈夫か!?"},"kind":"dialogue"},{"uid":"talk.ch4_3_4025#originalText","id":"talk.ch4_3_4025","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……注意你的言行。","en":"Watch your hands...","ja":"……言動には気をつけなさい"},"kind":"dialogue"},{"uid":"talk.ch4_3_4025_2#originalText","id":"talk.ch4_3_4025_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我有权夺走你们的七成天命。","en":"I have the authority to take 70% of your life.","ja":"私には、お前たちの天命の7割までを奪う権利があります"},"kind":"dialogue"},{"uid":"talk.ch4_3_4026#originalText","id":"talk.ch4_3_4026","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"下次再未经许可就想触碰我， 我就把你的手砍掉。","en":"If you try to touch me again, I will cut off your hand.","ja":"次に許可なく触れようとしたらその手を斬り落とします"},"kind":"dialogue"},{"uid":"talk.ch4_3_4027#originalText","id":"talk.ch4_3_4027","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"…………爱丽丝……","en":"Alice...","ja":"…………アリス……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4028#originalText","id":"talk.ch4_3_4028","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这名骑士就是你在找的 《爱丽丝》啊。","en":"So that knight is the \"Alice\" you've been searching for?","ja":"あの騎士が、お前の捜していた《アリス》なんだな"},"kind":"dialogue"},{"uid":"talk.ch4_3_4029#originalText","id":"talk.ch4_3_4029","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……现在先遵照她的指示。","en":"We should do as we're told for now.","ja":"……この場は指示に従おう"},"kind":"dialogue"},{"uid":"talk.ch4_3_4030#originalText","id":"talk.ch4_3_4030","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就算是以罪人的身分， 只要进入中央圣堂应该就能 明白一些事情才对。","en":"Even as criminals, as long as we're in the Central Cathedral, we should learn something.","ja":"罪人としてでもセントラル・カセドラルに入れさえすれば、少しは事情が解るはずだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_4031#originalText","id":"talk.ch4_3_4031","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4032#originalText","id":"talk.ch4_3_4032","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"跟我来， 上级修剑士尤吉欧、 上级修剑士桐人。","en":"Come with me, Elite Disciples Eugeo and Kirito.","ja":"ついてきなさい上級修剣士ユージオ、上級修剣士キリト"},"kind":"dialogue"},{"uid":"talk.ch4_3_4033#originalText","id":"talk.ch4_3_4033","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你们因触犯禁忌条例而须加以逮捕， 并在带往央都接受审问后处刑。","en":"For Taboo infringements, you shall be arrested, jailed, questioned, then executed.","ja":"そなたらを、禁忌条項抵触の咎により捕縛、連行し、審問ののち処刑します"},"kind":"dialogue"},{"uid":"talk.ch4_3_4034#originalText","id":"talk.ch4_3_4034","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"修剑学院‧大修练场前的广场","en":"Swordcraft Academy - Main Training Hall Grounds","ja":"修剣学院・大修練場前のグラウンド"},"kind":"caption"},{"uid":"talk.ch4_3_4035#originalText","id":"talk.ch4_3_4035","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"很好。","en":"There.","ja":"よし"},"kind":"dialogue"},{"uid":"talk.ch4_3_4036#originalText","id":"talk.ch4_3_4036","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"缇洁……","en":"Tiese...","ja":"ティーゼ……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4037#originalText","id":"talk.ch4_3_4037","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"罗妮耶！","en":"Ronie!","ja":"ロニエ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_4038#originalText","id":"talk.ch4_3_4038","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"骑、骑士大人…… 有件事要拜托您！","en":"L-Lady Knight, I have a request!","ja":"き、騎士様……お願いがございます!"},"kind":"dialogue"},{"uid":"talk.ch4_3_4039#originalText","id":"talk.ch4_3_4039","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"请您允许我们把学长的剑 归还给他们……！","en":"May we be permitted to return our mentors their swords?","ja":"先輩たちに、剣をお返しする許可をどうか……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_4040#originalText","id":"talk.ch4_3_4040","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……好吧。","en":"Very well.","ja":"……いいでしょう"},"kind":"dialogue"},{"uid":"talk.ch4_3_4040_2#originalText","id":"talk.ch4_3_4040_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不过，不能让罪人带剑。这个就交给我吧。","en":"However, I cannot allow the swords on their person. I will keep them.","ja":"ただし、罪人に剣を帯びさせるわけにはいかないそれは私が預かります"},"kind":"dialogue"},{"uid":"talk.ch4_3_4041#originalText","id":"talk.ch4_3_4041","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如果想跟他们交谈， 我给妳们一分钟的时间。","en":"I will allow you one minute to speak with them.","ja":"会話をするなら1分間に限って許可します"},"kind":"dialogue"},{"uid":"talk.ch4_3_4042#originalText","id":"talk.ch4_3_4042","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"尤吉欧学长……对不起…… 都……都是我害的……","en":"Eugeo...I'm so sorry. It's all my fault.","ja":"ユージオ先輩……ごめんなさい……私の……私のせいで……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4043#originalText","id":"talk.ch4_3_4043","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……因为我…… 愚蠢的举动……而害你……","en":"If only I weren't...so foolish...","ja":"……私が……愚かなことを……したせいで……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4044#originalText","id":"talk.ch4_3_4044","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不对……不是那样。","en":"No... You weren't foolish.","ja":"違うよ……違うんだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_4045#originalText","id":"talk.ch4_3_4045","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"妳没有错…… 妳为朋友做出了正确的事。","en":"You did nothing wrong, Tiese. You fought for your friend. You did the right thing.","ja":"ティーゼは悪くない……君は、友達のために正しいことをしたんだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_4046#originalText","id":"talk.ch4_3_4046","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……会变成这样，全都是我的错。妳没有必要道歉。","en":"It was my choice. You don't need to apologize for anything, Tiese.","ja":"……こうなったのは、全部僕のせいだティーゼが謝ることなんて何もないんだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_4047#originalText","id":"talk.ch4_3_4047","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这次……","en":"Next time...","ja":"今度は……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4048#originalText","id":"talk.ch4_3_4048","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这次换我来救尤吉欧学长。","en":"Next time, I will rescue you, Eugeo.","ja":"今度は、私がユージオ先輩を助けます"},"kind":"dialogue"},{"uid":"talk.ch4_3_4048_2#originalText","id":"talk.ch4_3_4048_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我一定…… 会努力成为集成骑士。然后去救出学长……","en":"I'll do my best and become an Integrity Knight... I promise I will come rescue you. ","ja":"私……頑張って、きっと整合騎士になって先輩を助けにいきますから……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4049#originalText","id":"talk.ch4_3_4049","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"所以，请你一定要等我。我一定……一定会……","en":"So...wait for me. I promise... I promise...","ja":"だから、待ってて下さいねきっと……きっと……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4050#originalText","id":"talk.ch4_3_4050","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"那个……这是便当。肚子饿的时候，请吃这个便当吧……","en":"And...here's lunch we made. Please, eat it when you get hungry...","ja":"あの……これ、お弁当ですお腹が空いたら、食べてください……"},"kind":"dialogue"},{"uid":"talk.ch4_3_4051#originalText","id":"talk.ch4_3_4051","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"时间到了， 快点离开。","en":"It's time. Leave.","ja":"時間です離れなさい"},"kind":"dialogue"},{"uid":"talk.ch4_3_4052#originalText","id":"talk.ch4_3_4052","speaker":{"cn":"飞龙","en":"Wyvern","ja":"飛竜"},"text":{"cn":"啾……","en":"Grrr!","ja":"ぎゅるるっ……"},"kind":"dialogue"},{"uid":"talk.ch4_3_1050_2#originalText","id":"talk.ch4_3_1050_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"真是太谢谢你了， 我想芙蕾妮卡也会很高兴的。","en":"Thank you so much! Frenica will be so happy to hear that.","ja":"ありがとうございますフレニーカも喜ぶと思います"},"kind":"dialogue"},{"uid":"talk.ch4_3_2011#originalText","id":"talk.ch4_3_2011","speaker":{"cn":"芙蕾妮卡","en":"Frenica"},"text":{"cn":"今天晚上……","en":"He still orders me to perform those tasks, "},"kind":"dialogue"},{"uid":"talk.ch4_3_2100#originalText","id":"talk.ch4_3_2100","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……雨渐渐变大了。","en":"It's raining harder now.","ja":"……雨が強くなってきたな"},"kind":"dialogue"},{"uid":"talk.ch4_3_2101#originalText","id":"talk.ch4_3_2101","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我有种不好的预感…… 快点回去吧。","en":"I've got a bad feeling about this...","ja":"嫌な予感がする……急いで帰ろう"},"kind":"dialogue"},{"uid":"talk.ch4_3_2331#originalText","id":"talk.ch4_3_2331","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"可以行使《贵族裁决权》！","en":"I have \"judicial authority\" over them!","ja":"《貴族裁決権》を行使できるのだよ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2332#originalText","id":"talk.ch4_3_2332","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……！","en":"...!","ja":"……っ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2333#originalText","id":"talk.ch4_3_2333","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"乖乖地别动， 我接下来要好好的指导妳。","en":"Now, now. Take your punishment in a dignified manner.","ja":"大人しくしろ指導をしてやろうというのだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2334#originalText","id":"talk.ch4_3_2334","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"住手……！！","en":"Stop it!!","ja":"やめろっ……!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2335#originalText","id":"talk.ch4_3_2335","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"别乱动，平民！！","en":"Don't move, commoner!!","ja":"動くな、平民!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2336#originalText","id":"talk.ch4_3_2336","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"这是根据帝国基本法以及 禁忌目录所运行，","en":"What I am about to do is my divine right,","ja":"これから行うことは"},"kind":"dialogue"},{"uid":"talk.ch4_3_2336_2#originalText","id":"talk.ch4_3_2336_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"正当且严肃的贵族裁决！","en":"granted by the Taboo Index and Basic Imperial Law.","ja":"帝国基本法及び禁忌目録に則った正当、厳粛なる貴族の裁決である!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2337#originalText","id":"talk.ch4_3_2337","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"妨碍裁决权也是严重的违法行为！","en":"Obstruction of judicial authority is a serious crime!","ja":"裁決権の妨害もまた重大な違法行為だ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2338#originalText","id":"talk.ch4_3_2338","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"你要是再动一步的话， 就会变成违背法律的罪人！","en":"If you move one inch closer, you will be a criminal!","ja":"そこから一歩でも動いたらお前は法を破った罪人となるのだ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2339#originalText","id":"talk.ch4_3_2339","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"谁……（谁理你什么法律！）","en":"No... (No way am I accepting that!!)","ja":"そ……(んなこと、知ったことか!)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2340#originalText","id":"talk.ch4_3_2340","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（我的脚！？不听使唤！？）","en":"(My leg?! It's frozen?!)","ja":"(脚が!? 動かない!?)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2341#originalText","id":"talk.ch4_3_2341","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不要、不要……","en":"No! Stop!","ja":"いやっ、いや……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2342#originalText","id":"talk.ch4_3_2342","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长、学长……","en":"Eugeo...!","ja":"先輩、先輩……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2343#originalText","id":"talk.ch4_3_2343","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（唔……！！动啊！！快动啊！！）","en":"(Umph! Move! Move!!!)","ja":"(ぐ……っ……!! 動け!! 動け!!)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2400#originalText","id":"talk.ch4_3_2400","speaker":{},"text":{"cn":"莱欧斯的寝室","en":"Raios' Bedroom","ja":"ライオスの寝室"},"kind":"narration"},{"uid":"talk.ch4_3_2401#originalText","id":"talk.ch4_3_2401","speaker":{},"text":{"cn":"数日前","en":"A Few Days Earlier","ja":"数日前"},"kind":"narration"},{"uid":"talk.ch4_3_2402#originalText","id":"talk.ch4_3_2402","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就算法律没有禁止， 有些事情还是不能去做……","en":"There are things you shouldn't do, even if they're not forbidden by law.","ja":"たとえ法で禁じられていなくてもしてはいけないことは存在するし……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2403#originalText","id":"talk.ch4_3_2403","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"而相反的，就算法律禁止， 有些事情也必须去做。","en":"And conversely, we sometimes must break unjust laws.","ja":"また逆に、法で禁じられていたとしてもしなきゃいけないことだってあるかもしれない"},"kind":"dialogue"},{"uid":"talk.ch4_3_2404#originalText","id":"talk.ch4_3_2404","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（允许用强硬手段凌辱未婚少女的 法律究竟是怎么回事？）","en":"(What sort of law allows a man to force himself on unwilling girls?)","ja":"(婚姻前の少女を力尽くで陵辱することを許す法とはいったい何なのか?)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2405#originalText","id":"talk.ch4_3_2405","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（这样的法律有存在的意义吗？）","en":"(What value does such a law have?)","ja":"(そんな法に何の存在価値があるのか?)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2406#originalText","id":"talk.ch4_3_2406","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔！！ （右眼好痛！！）","en":"Ugh!! (My right eye hurts so much!!)","ja":"グッ!!(右眼が痛い!!)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2407#originalText","id":"talk.ch4_3_2407","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（所有的法律与禁忌，都是为了让人界的所有人民能够过着幸福日子而存在。）","en":"(All laws and taboos exist to keep everyone in the human realm lead peaceful, happy lives.)","ja":"(あらゆる法や禁忌は人界全ての民が日々幸せに過ごすために存在している)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2408#originalText","id":"talk.ch4_3_2408","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（但是， 为什么这些法律都只有《禁止》呢？）","en":"(But why do all of these laws only \"forbid\" us to do things?)","ja":"(しかし、なぜそれらの法は《禁じる》だけなのか)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2409#originalText","id":"talk.ch4_3_2409","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（只要在禁忌目录写上『任何人 都必须尊重敬爱他人，）","en":"(Why doesn't the Taboo Index have a rule that says,)","ja":"『誰もが誰もを尊重し、敬意を払い、仁愛の心を持て』"},"kind":"dialogue"},{"uid":"talk.ch4_3_2409_2#originalText","id":"talk.ch4_3_2409_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（同时抱持 一颗仁爱之心』不就好了吗？）","en":"(\"treat others with respect and goodwill\"?)","ja":"(禁忌目録にそうひとこと記せばいいだけではないか)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2410#originalText","id":"talk.ch4_3_2410","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……也就是说， 这是不可能的。","en":"In other words...it's impossible. Even with the authority of the church,","ja":"……つまり、不可能なんだ教会の権威を以ってしても"},"kind":"dialogue"},{"uid":"talk.ch4_3_2411#originalText","id":"talk.ch4_3_2411","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就算有教会的权威， 也不可能让所有人类都只保持善心。","en":"they can't make everyone's hearts purely virtuous.","ja":"全ての人に善心のみをもたせることはできないんだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2412#originalText","id":"talk.ch4_3_2412","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"因为……","en":"And if that's the case...","ja":"なぜなら……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2413#originalText","id":"talk.ch4_3_2413","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"人类原本就是拥有 善恶两种心肠的存在──","en":"Since humans are born with good and evil inside...","ja":"人間とはもともと善と悪の両方を持つ存在だからーー"},"kind":"dialogue"},{"uid":"talk.ch4_3_2414#originalText","id":"talk.ch4_3_2414","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不、不要……不要……不要…………！","en":"No! No...no...no...!","ja":"い、いや……いや……いや…………!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2415#originalText","id":"talk.ch4_3_2415","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不要……救救我……救救我吧， 尤吉欧学长！","en":"No...help...save me... Eugeo!","ja":"いや……助けて……たすけてユージオ先輩!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2416#originalText","id":"talk.ch4_3_2416","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"尤吉欧学长──！","en":"Eugeo, save me!","ja":"ユージオせんぱい――っ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2417#originalText","id":"talk.ch4_3_2417","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（鼓起勇气展开行动的 缇洁与罗妮耶……）","en":"(Tiese and Ronie were brave to stand up for their friend.)","ja":"(勇気を振り絞って行動を起こしたティーゼとロニエに……)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2418#originalText","id":"talk.ch4_3_2418","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（法律却给予她们如此残酷的惩罚。）","en":"(And this is the cruel punishment the law gives them.)","ja":"(これほどの残酷な罰を与える法)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2419#originalText","id":"talk.ch4_3_2419","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（如果遵守这样的法律才叫良善──）","en":"(And if following that \"law\" makes me a \"good\" person...)","ja":"(そんな法を守ることが善だというのなら――)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2420#originalText","id":"talk.ch4_3_2420","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那么我…………我！","en":"Then I...I can't...!","ja":"僕は…………僕は!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2421#originalText","id":"talk.ch4_3_2421","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"──！！！！","en":"Mmm!!!!","ja":"――ッッッッ!!!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2422#originalText","id":"talk.ch4_3_2422","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（右眼里有东西……！？ ……这是……什么！？）","en":"(There's something...in my right eye?! What...is this thing?!)","ja":"(右眼に何かが……!?………なんだ……これは!?)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2423#originalText","id":"talk.ch4_3_2423","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（……好痛……这…… ……这和六年前一样……！！）","en":"(It hurts... This is the same sensation from six years ago!!!)","ja":"(……痛い……。これは…………6年前と同じ…!!)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2500#originalText","id":"talk.ch4_3_2500","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔……咕……喔喔……！","en":"Ugh... Mmf... Argh!","ja":"う……ぐ……おお……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2501#originalText","id":"talk.ch4_3_2501","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（饶不了温贝尔和莱欧斯…… 我绝对……饶不了他们……！！）","en":"(Humbert and Raios will pay... I will give them Hell for what they've done!!)","ja":"(ウンベールとライオスは許せない……絶対に…許せない……!!)"},"kind":"dialogue"},{"uid":"talk.ch4_3_2502#originalText","id":"talk.ch4_3_2502","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"喂！！给我老实点！！","en":"Hey!! Stay still!!","ja":"おい!! じっとしてろ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2503#originalText","id":"talk.ch4_3_2503","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不、不要────！！","en":"No, no!!","ja":"や、嫌ああ――――ッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2504#originalText","id":"talk.ch4_3_2504","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长────！！","en":"Eugeo!!","ja":"先輩――――ッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2505#originalText","id":"talk.ch4_3_2505","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔……喔喔喔啊啊啊────！！","en":"Grrraaaah!!","ja":"う……おおおああ――――ッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2506#originalText","id":"talk.ch4_3_2506","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喝啊啊啊啊────！！","en":"Yahhh!!","ja":"せああああ――――ッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2507#originalText","id":"talk.ch4_3_2507","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"噫……啊啊…… 啊啊啊啊啊────！？","en":"No...ohh... Ahhh?!","ja":"い……ああ……あああああ――――ッ!?"},"kind":"dialogue"},{"uid":"talk.ch4_3_2508#originalText","id":"talk.ch4_3_2508","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"我……我……我的手臂……！ 血……流出一大堆血了…………！！","en":"M-my arm! My arm! Blood...","ja":"う……腕……オレの腕がっ……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2508_2#originalText","id":"talk.ch4_3_2508_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"天命一直在减少啊啊啊！！","en":"So much blood!! My life is draining awaaay!!","ja":"血がっ……血がこんなにっ…………!!天命が減っていくうううっ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2509#originalText","id":"talk.ch4_3_2509","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"莱、莱欧斯同学！快用神圣术！ 普通的术式已经来不及了……","en":"R-Raios! Your Sacred Arts! N-Normal arts would be too slow,","ja":"ら、ライオス殿っ! 神聖術をっ!普通の術じゃ間に合わないっ……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2509_2#originalText","id":"talk.ch4_3_2509_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"请、请把天命分给我吧……！！","en":"please, give me some of your life!","ja":"天命を、天命を分けてくださいっ……!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2510#originalText","id":"talk.ch4_3_2510","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"别鬼叫了，少掉一只手不会让天命 完全消失。","en":"Stop whining. It's just one arm. You won't die from it.","ja":"そう喚くな。腕1本落ちたくらいで天命がなくなりはしない"},"kind":"dialogue"},{"uid":"talk.ch4_3_2510_2#originalText","id":"talk.ch4_3_2510_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"先用丝绢绳子缠起来， 别让血继续流了。","en":"Wrap it with that cord and stop the blood.","ja":"その絹紐でも巻いて、血を止めておけ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2511#originalText","id":"talk.ch4_3_2511","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"怎、怎么这样……","en":"B-but...","ja":"そ、そんな……"},"kind":"dialogue"},{"uid":"talk.ch4_3_2512#originalText","id":"talk.ch4_3_2512","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"太了不起了……我还是…… 第一次看见犯下如此禁忌的人。","en":"Impressive... I have never seen anyone break the Taboos like this.","ja":"素晴らしい……こんな……ここまでの禁忌を犯す人間を、私は初めて見た"},"kind":"dialogue"},{"uid":"talk.ch4_3_2513#originalText","id":"talk.ch4_3_2513","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"原则上贵族裁决权的对象 就只有下级贵族与私人领地上的人民，","en":"Judicial authority is applied only to lower nobles, in principle.","ja":"貴族裁決権の対象は原則として下級貴族と私領地民だけだが"},"kind":"dialogue"},{"uid":"talk.ch4_3_2513_2#originalText","id":"talk.ch4_3_2513_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"但犯了禁忌的大罪人则不在此限！","en":"But taboo-breaking is a special case!","ja":"禁忌を犯した大罪人とあらばその限りではない!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2514#originalText","id":"talk.ch4_3_2514","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"…………","en":"...","ja":"…………"},"kind":"dialogue"},{"uid":"talk.ch4_3_2515#originalText","id":"talk.ch4_3_2515","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"哼，冲击太大，动弹不得了吗？","en":"Humph. The attack knocked you paralyzed?","ja":"フンッ、衝撃で身動きが取れないか"},"kind":"dialogue"},{"uid":"talk.ch4_3_2516#originalText","id":"talk.ch4_3_2516","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"呵呵…… 我还是第一次用剑砍下别人的头。","en":"Hehe. This will be my first time beheading anyone.","ja":"くく……剣で人の首を落とすのは初めてだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2516_2#originalText","id":"talk.ch4_3_2516_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"这样，我就会变得更加强大。","en":"It will make me even stronger.","ja":"これで私はさらに強くなる"},"kind":"dialogue"},{"uid":"talk.ch4_3_2517#originalText","id":"talk.ch4_3_2517","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"大罪人尤吉欧！！","en":"Eugeo, the sinner!!","ja":"大罪人ユージオ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2517_2#originalText","id":"talk.ch4_3_2517_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"我莱欧斯‧安提诺斯，身为三等爵士家 嫡长子，依照贵族裁决权将你处决！！","en":"I, Raois Antinous, nobleman of the 3rd rank, sentence you to death!!","ja":"三等爵士嫡男たる、このライオス・アンティノスが汝を貴族裁決権により処刑する!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_2518#originalText","id":"talk.ch4_3_2518","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"──！","en":"Ffft.","ja":"――ッ"},"kind":"dialogue"},{"uid":"talk.ch4_3_2519#originalText","id":"talk.ch4_3_2519","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐……人……","en":"Kiri...to...","ja":"キリ……ト…………"},"kind":"dialogue"},{"uid":"talk.ch4_3_2520#originalText","id":"talk.ch4_3_2520","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莱欧斯，收起你的剑。","en":"Draw your sword, Raios.","ja":"剣を引け、ライオス"},"kind":"dialogue"},{"uid":"talk.ch4_3_2521#originalText","id":"talk.ch4_3_2521","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我不会让你伤害尤吉欧。","en":"I won't let you hurt Eugeo.","ja":"お前にユージオは傷つけさせない"},"kind":"dialogue"},{"uid":"talk.ch4_3_3000#originalText","id":"talk.ch4_3_3000","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"你终于来了吗，桐人修剑士。","en":"Finally making an appearance, Kirito? ","ja":"ようやくのお出ましか、キリト修剣士"},"kind":"dialogue"},{"uid":"talk.ch4_3_3000_2#originalText","id":"talk.ch4_3_3000_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"不过，你来得有点太迟了！","en":"You're too late!","ja":"しかし、少々遅すぎたぞ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3001#originalText","id":"talk.ch4_3_3001","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"那个乡巴佬，现在是违犯禁忌目录的 大罪人！你才该退下在一旁看着。","en":"That filthy boar broke the Taboo Index! So stand back and watch!","ja":"そこの田舎者は、禁忌目録に背いた大罪人だ!お前こそ下がって、そこで見ていろ"},"kind":"dialogue"},{"uid":"talk.ch4_3_3002#originalText","id":"talk.ch4_3_3002","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"看着这个罪人的首级， 像过去那些花一样地散落！！","en":"Gape as this sinner's head falls like your flowers!!","ja":"いつぞやの花のようにこの罪人の首が落ちるさまをなァ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3003#originalText","id":"talk.ch4_3_3003","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"谁理你什么禁忌，还是贵族权利！","en":"Think I care about taboos, nobles, or birthrites?!","ja":"禁忌だの、貴族の権利だの、知ったことか!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3004#originalText","id":"talk.ch4_3_3004","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"尤吉欧是我最好的朋友， 而你则是……","en":"Eugeo is my friend! And as for you...","ja":"ユージオは俺の親友だそしてお前は……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3005#originalText","id":"talk.ch4_3_3005","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"比暗之国的哥布尔还不如的人渣！！","en":"I know Goblins that are more chivalrous than you!","ja":"闇の国のゴブリンにも劣る屑野郎だ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3006#originalText","id":"talk.ch4_3_3006","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"没想到边境的两个乡巴佬 竟然会一起犯下大逆不道之罪！","en":"So the filthy peasants commit treason together!","ja":"辺境の田舎者同士仲良く大逆の罪を犯してくれるとはな!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3007#originalText","id":"talk.ch4_3_3007","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"这样我就可以把你们两个 一并处决了。","en":"Looks like I can execute you both at the same time.","ja":"これで私はお前たちを揃って処分できるわけだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_3008#originalText","id":"talk.ch4_3_3008","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"这一定是史提西亚神的引导啊！！","en":"If this isn't the will of Stacia, I don't know what is!!","ja":"これぞ、ステイシア神の導きというものだァ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3009#originalText","id":"talk.ch4_3_3009","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（……我要站起来……）","en":"(Stand up...)","ja":"(……立ち上がるんだ……)"},"kind":"dialogue"},{"uid":"talk.ch4_3_3010#originalText","id":"talk.ch4_3_3010","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"别担心，尤吉欧。","en":"It's okay, Eugeo.","ja":"大丈夫だ、ユージオ"},"kind":"dialogue"},{"uid":"talk.ch4_3_3011#originalText","id":"talk.ch4_3_3011","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"（……剑变长了……！？）","en":"(The sword is stretching..?!)","ja":"(……剣が伸びた!?……)"},"kind":"dialogue"},{"uid":"talk.ch4_3_3012#originalText","id":"talk.ch4_3_3012","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"呵、呵呵呵……看我用秘藏奥义直接粉碎这种剑技！！","en":"Ha! Time to smash that junk toy of yours!","ja":"く、くふふ……そんな代物は我が秘奥義で打ち砕いてくれるわあッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3013#originalText","id":"talk.ch4_3_3013","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"来啊，莱欧斯！！","en":"Come, Raios!","ja":"来い、ライオス!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3100#originalText","id":"talk.ch4_3_3100","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"喝啊啊啊啊啊啊！！","en":"Yahhh!!","ja":"キェアアアアアアッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3100_1#originalText","id":"talk.ch4_3_3100_1","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"没想到你们竟然会犯下大逆不道之罪！","en":"To think you'd go and commit the greatest crime!","ja":"まさかそちらから大逆の罪を犯してくれるとはなっ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3100_2#originalText","id":"talk.ch4_3_3100_2","speaker":{"cn":"莱欧斯","en":"Raios"},"text":{"cn":"你们这种没有姓氏的平民别想超越我！！","en":"I won't be second to you nameless pesants!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3101#originalText","id":"talk.ch4_3_3101","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……唔！","en":"Ha!!","ja":"……くっ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3101_1#originalText","id":"talk.ch4_3_3101_1","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"这样我就可以把你们两个一并处决了！","en":"Now I'm free to dispose of you!","ja":"これで私は、お前を処分できるということだ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3101_2#originalText","id":"talk.ch4_3_3101_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"赝品对我的剑可没有效啊啊啊啊啊啊啊啊－－！","en":"Your tricks won't work against meee!!!","ja":"我が剣にまやかしは効かぬぞおおォォォーー!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3102#originalText","id":"talk.ch4_3_3102","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"像你这种低贱的平民！！","en":"Filthy peasant! How dare you!!","ja":"貴様ごとき平民にッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3103#originalText","id":"talk.ch4_3_3103","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"我莱欧斯‧安提诺斯……","en":"I am the great Raios Antinous.","ja":"このライオス・アンティノス様が"},"kind":"dialogue"},{"uid":"talk.ch4_3_3104#originalText","id":"talk.ch4_3_3104","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"才不会输给你────！！","en":"I will not be defeated by the likes of YOU!!","ja":"後れを取るわけがないのだァァ――――ッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3105#originalText","id":"talk.ch4_3_3105","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……桐人的招式是── 索尔缇莉娜学姊的……","en":"Kirito's technique, that's...Sortiliena's...","ja":"……キリトの技は――ソルティリーナ先輩の……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3106#originalText","id":"talk.ch4_3_3106","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"唔……喔喔喔！！","en":"Grrraaah!!","ja":"う……おおおッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3107#originalText","id":"talk.ch4_3_3107","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"────！！","en":"...Ugh!!","ja":"――――ッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3200#originalText","id":"talk.ch4_3_3200","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"噫……噫…… 噫啊啊啊啊啊啊啊啊啊啊────！！","en":"G...rr... rrraaah!!!","ja":"い……イ……イアアアアアアアァァァ――――ッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3201#originalText","id":"talk.ch4_3_3201","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"手……手臂！！我的手臂啊啊啊！！ 流、流血了！！","en":"M-my arm! My arrrm!!! Blood...so much blood!!","ja":"う……腕ェッ!! 私の腕があああッ!!血が、血が出ているッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3202#originalText","id":"talk.ch4_3_3202","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"温贝尔────！！ 帮我！！快帮我止血！！","en":"Humberrrt!!! Stop my blood!! Make it stop!!","ja":"ウンベエエェェェルッ!!血をッ!! 私の血を止めろッ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3203#originalText","id":"talk.ch4_3_3203","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"才、才不要！ 把、把这解开，我的天命就会减少！！","en":"N-no! If I undo this, I will lose my life!","ja":"い、嫌だ!こ、これを解いたら、オレの天命が減る!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3204#originalText","id":"talk.ch4_3_3204","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"你这命令违反禁忌目录！","en":"That order breaks the Taboo Index!","ja":"その命令は禁忌目録違反だ!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3205#originalText","id":"talk.ch4_3_3205","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"禁忌！？可是……我的血……温贝尔， 你……禁忌……可是……天命……","en":"Taboo?! But...I'm bleeding... Humbert! Taboo...but...my life!","ja":"禁忌ィ!? だが……私の血がッ……ウンベールッお前ッ……禁忌……しかしッ……天命がッ……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3206#originalText","id":"talk.ch4_3_3206","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"啊啊啊啊……禁忌……天命…… 血……禁忌…………","en":"Ahhh! Taboo...life...blood... Taboooo...","ja":"ああああッ……禁忌……天命……血ぃ……禁忌いいぃぃぃ…………"},"kind":"dialogue"},{"uid":"talk.ch4_3_3207#originalText","id":"talk.ch4_3_3207","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂、喂……用这个止血吧……","en":"H-here! Stop the blood with this...","ja":"お、おい……これで止血を……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3208#originalText","id":"talk.ch4_3_3208","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"天命、禁忌、天命、禁忌、 天、天、天、天天天天……","en":"Life...Taboo...life... Taboo...li...li...lililili...","ja":"てんめい、きんぎ、でんめいぎんぎ、でん、で、で、でででで"},"kind":"dialogue"},{"uid":"talk.ch4_3_3209#originalText","id":"talk.ch4_3_3209","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"天天天、天、天命、天命天命天命、 天命天命天命天命天────────","en":"Lilili! Li! Li! L-l-l-l-l-l-l-l-l","ja":"でででっ、でっ、でっ、ディッ、ディル、ディルディルディル、ディルディルディルディルディ"},"kind":"dialogue"},{"uid":"talk.ch4_3_3300#originalText","id":"talk.ch4_3_3300","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"天命天命天命天命天────────","en":"Lilili! Li! Li! L-l-l-l-l-l-l-l-l","ja":"ディルディルディルディルディ――――――――"},"kind":"dialogue"},{"uid":"talk.ch4_3_3301#originalText","id":"talk.ch4_3_3301","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"…………","en":"...","ja":"…………"},"kind":"dialogue"},{"uid":"talk.ch4_3_3302#originalText","id":"talk.ch4_3_3302","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（……不动了。他是……死了吗？）","en":"(He's not moving. Is he...dead?)","ja":"(……動かない死んでる……のか?)"},"kind":"dialogue"},{"uid":"talk.ch4_3_3303#originalText","id":"talk.ch4_3_3303","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（刚才那到底是……？ 摇光发生什么事了吗？）","en":"(What just...happened? Did something happen to his fluctlight?)","ja":"(今のは一体……?フラクトライトに何かあったのか?)"},"kind":"dialogue"},{"uid":"talk.ch4_3_3304#originalText","id":"talk.ch4_3_3304","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"噫、噫──！！","en":"Ee-eep!! ","ja":"ひ、ひいいっ!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3304_2#originalText","id":"talk.ch4_3_3304_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"莱、莱、莱欧斯同学…… 死、死、死了……！","en":"R-R-Raios! He's d-d-dead!","ja":"らっ、らっ、ライオス殿が……し、し、死んで……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3305#originalText","id":"talk.ch4_3_3305","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"你、你、你杀了他…… 你杀了他、你杀了他！！杀人犯……","en":"You k-k-killed...killed...killed him!!","ja":"こっ、ころっ、殺した……殺した、殺したっ!! 人殺し……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3305_2#originalText","id":"talk.ch4_3_3305_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"怪、怪物……怪物……！！","en":"Murderer...mon-monster!!","ja":"ばっ、化け……化け物っ……!!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3306#originalText","id":"talk.ch4_3_3306","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"对不起…… 对不起，尤吉欧学长……","en":"I'm sorry... I'm so sorry, Eugeo...","ja":"ごめんなさい……ごめんなさい、ユージオ先輩……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3306_2#originalText","id":"talk.ch4_3_3306_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"都是……都是我害的……！","en":"It's all my fault!","ja":"私……わたしのせいで……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3307#originalText","id":"talk.ch4_3_3307","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不对，这不是妳的错。","en":"No, Tiese, it's not your fault.","ja":"違うよ、ティーゼのせいじゃない"},"kind":"dialogue"},{"uid":"talk.ch4_3_3307_2#originalText","id":"talk.ch4_3_3307_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是我……是我思虑不周， 不是妳的责任。","en":"I didn't think things  through enough.","ja":"僕が……僕の考えが足りなかったからだティーゼには何の責任もない"},"kind":"dialogue"},{"uid":"talk.ch4_3_3308#originalText","id":"talk.ch4_3_3308","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"可、可是……可是……！","en":"B-but...but...!","ja":"で、でも……でも……!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3309#originalText","id":"talk.ch4_3_3309","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没关系啦，妳和罗妮耶都平安 无事就好……对不起，","en":"It's okay. I'm just glad you're safe...","ja":"いいんだ、ティーゼとロニエが無事だったんだから……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3309_2#originalText","id":"talk.ch4_3_3309_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"让妳们遇见这么恐怖的事情。","en":"I'm so sorry you had to go through that.","ja":"ごめん、怖い思いをさせてしまって"},"kind":"dialogue"},{"uid":"talk.ch4_3_3310#originalText","id":"talk.ch4_3_3310","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……那是什么！","en":"What was that?!","ja":"……なんだあれは!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3311#originalText","id":"talk.ch4_3_3311","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"…………之前好像在哪里……","en":"W-Where...","ja":"…………前に、どこかで……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3311_2#originalText","id":"talk.ch4_3_3311_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我好像很久之前在哪里见过他。","en":"Where have I seen this before?","ja":"僕は、ずっと昔どこかであいつを見ている"},"kind":"dialogue"},{"uid":"talk.ch4_3_3312#originalText","id":"talk.ch4_3_3312","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"别让缇洁她们听到！","en":"Don't let Tiese and Ronie hear!","ja":"ティーゼたちに聞かせるな!"},"kind":"dialogue"},{"uid":"talk.ch4_3_3313#originalText","id":"talk.ch4_3_3313","speaker":{"cn":"可疑的头","en":"Mysterious Severed Head","ja":"怪しい首"},"text":{"cn":"Singular unit detected。ID tracing……","en":"Singular Unit Detected. ID Tracing...","ja":"シンギュラー・ユニット・ディテクティドアイディー・トレーシング……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3314#originalText","id":"talk.ch4_3_3314","speaker":{"cn":"可疑的头","en":"Mysterious Severed Head","ja":"怪しい首"},"text":{"cn":"Coordinate fixed。Report complete。","en":"Coordinate Fixed Report Complete.","ja":"コーディネート・フィクストリポート・コンプリート"},"kind":"dialogue"},{"uid":"talk.ch4_3_3315#originalText","id":"talk.ch4_3_3315","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch4_3_3316#originalText","id":"talk.ch4_3_3316","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……我已经和那些哥布尔一样了。","en":"I'm just like those Goblins.","ja":"……僕はもうあのゴブリンたちと同じだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_3317#originalText","id":"talk.ch4_3_3317","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你是人类啊，尤吉欧。和我一样……","en":"No, you're human, Eugeo. Just like me.","ja":"お前は人間だ、ユージオ。俺と同じ"},"kind":"dialogue"},{"uid":"talk.ch4_3_3317_2#originalText","id":"talk.ch4_3_3317_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是虽然会犯一些错，但还是拼命 寻找其意义，不断挣扎的……人类。","en":"You make mistakes and try to fix them.","ja":"……間違いを犯しては、その意味を探して足掻きつづける……人間なんだ"},"kind":"dialogue"},{"uid":"talk.ch4_3_3318#originalText","id":"talk.ch4_3_3318","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人……","en":"Kirito...","ja":"キリト……"},"kind":"dialogue"}]};
